column3:
}
let second_pool_barrier_start = pool.operations.len() - parameters.device_count;
pool.operations.truncate(second_pool_barrier_start);

// 第三段：根槽 FUA，区域 3 mod 3 = 0 的槽 1（暖机之后第一个事务是 txg 3）。

column2:
if let RecordedOperation::Write(write) = operation {
    writes.push(write.clone());
    current.push(writes.len() - 1);
}

column3:
if let RecordedOperation::Write(write) = operation {
    if fua_is_boundary && write.is_fua() && !current.is_empty() {
        segments.push(std::mem::take(&mut current));
    }
    writes.push(write.clone());
    current.push(writes.len() - 1);
}

column2:
// ⑧ 发布尾那道屏障（D16 已定项 7「根槽（FUA）→ 系统配置槽 → 屏障」，登记 R43）。
if parameters.issues_trailing_publish_barrier() {
    pool.barrier();
}

column3:
if parameters.issues_trailing_publish_barrier() {
    let before_system_configuration_writes = pool.operations.len() - parameters.device_count;
    for device_index in (0..parameters.device_count).rev() {
        pool.operations.insert(before_system_configuration_writes, RecordedOperation::Barrier(DeviceIdentity(u32::try_from(device_index).expect("设备数"))));
    }
}

column2:
// ⑧ 发布尾那道屏障（D16 已定项 7「根槽（FUA）→ 系统配置槽 → 屏障」，登记 R43）：每次空发布各一道。
if parameters.issues_trailing_publish_barrier() {
    pool.barrier();
}

// ⑧ 发布尾那道屏障（D16 已定项 7「根槽（FUA）→ 系统配置槽 → 屏障」，登记 R43）。
if parameters.issues_trailing_publish_barrier() {
    pool.barrier();
}
